const x = $input.first().json;
const issues = [];
let w = null;

if (x.ai_valid && x.ai_data) {
  w = x.ai_data.updated_workflow_json;
  if (!w || typeof w !== 'object' || Array.isArray(w)) {
    issues.push('updated_workflow_json must be object');
    w = null;
  }
}

if (w) {
  if (typeof w.name !== 'string' || !w.name.trim()) issues.push('workflow.name must be non-empty string');
  if (!Array.isArray(w.nodes)) issues.push('workflow.nodes must be array');
  else if (w.nodes.length === 0) issues.push('workflow.nodes must not be empty');
  if (!w.connections || typeof w.connections !== 'object' || Array.isArray(w.connections)) issues.push('workflow.connections must be object');
  if (w.settings !== undefined && (typeof w.settings !== 'object' || Array.isArray(w.settings))) issues.push('workflow.settings must be object when provided');
  if (w.active === true) issues.push('workflow.active must not be true');

  const nodes = Array.isArray(w.nodes) ? w.nodes : [];
  const ids = new Set(), names = new Set();

  for (const n of nodes) {
    if (!n || typeof n !== 'object') {
      issues.push('node entry invalid');
      continue;
    }
    const label = n.name || n.id || '(unnamed)';
    if (typeof n.id !== 'string' || !n.id.trim()) issues.push('node.id missing: ' + label);
    else if (ids.has(n.id)) issues.push('node.id duplicate: ' + n.id);
    else ids.add(n.id);

    if (typeof n.name !== 'string' || !n.name.trim()) issues.push('node.name missing: ' + label);
    else if (names.has(n.name)) issues.push('node.name duplicate: ' + n.name);
    else names.add(n.name);

    if (typeof n.type !== 'string' || !n.type.trim()) issues.push('node.type missing: ' + label);
    if (typeof n.typeVersion !== 'number' || !isFinite(n.typeVersion) || n.typeVersion < 0) issues.push('node.typeVersion invalid: ' + label);
    if (!n.parameters || typeof n.parameters !== 'object' || Array.isArray(n.parameters)) issues.push('node.parameters invalid: ' + label);
    if (!Array.isArray(n.position) || n.position.length !== 2 || typeof n.position[0] !== 'number' || typeof n.position[1] !== 'number') issues.push('node.position invalid: ' + label);

    if (n.credentials !== undefined && n.credentials !== null && n.credentials !== '[REDACTED]') {
      if (typeof n.credentials !== 'object' || Array.isArray(n.credentials)) {
        issues.push('node.credentials invalid format: ' + label);
      } else {
        const sensitiveCredKey = /(password|passwd|secret|token|api.?key|private.?key|client.?secret)/i;
        for (const [credType, credVal] of Object.entries(n.credentials)) {
          if (credVal && typeof credVal === 'object') {
            for (const k of Object.keys(credVal)) {
              if (sensitiveCredKey.test(k)) {
                issues.push('node.credentials must not contain inline secret keys (' + credType + '.' + k + '): ' + label);
              }
            }
          }
        }
      }
    }

    if (n.active === true) issues.push('node.active must not be true: ' + label);
  }

  if (w.connections && typeof w.connections === 'object') {
    const nameSet = new Set(names);
    for (const [srcName, groups] of Object.entries(w.connections)) {
      if (!nameSet.has(srcName)) issues.push('connection source missing: ' + srcName);
      if (!groups || typeof groups !== 'object' || Array.isArray(groups)) {
        issues.push('connection group invalid: ' + srcName);
        continue;
      }
      for (const outs of Object.values(groups)) {
        if (!Array.isArray(outs)) continue;
        for (const branch of outs) {
          if (!Array.isArray(branch)) continue;
          for (const edge of branch) {
            if (!edge || typeof edge.node !== 'string' || !nameSet.has(edge.node)) {
              issues.push('connection target missing: ' + String(edge && edge.node));
            }
          }
        }
      }
    }
  }

  const generatedStr = JSON.stringify(w);
  const secretPatterns = [/gsk_[a-zA-Z0-9]{20,}/, /sk-proj-[A-Za-z0-9_-]{20,}/, /\bsk-[a-zA-Z0-9]{20,}/, /AIza[\w-]{30,}/, /gh[pousr]_[A-Za-z0-9]{20,}/, /xox[baprs]-[A-Za-z0-9-]{10,}/, /Bearer\s+[A-Za-z0-9._~+\/-]{12,}=*/i];
  if (secretPatterns.some(re => re.test(generatedStr))) issues.push('updated JSON contains hardcoded secret pattern');
}

const ok = !!(w && issues.length === 0 && x.ai_valid);
return [{ json: { ...x, _wf: w, _structural_issues: issues, _structural_valid: ok } }];

const x = $input.first()?.json || {};
const valReq = $('Validate Request').first()?.json || {};

const reqId = valReq.request_id || x.request_id || 'fallback-id';
const userId = valReq.user_id || x.user_id || null;
const workspaceId = valReq.workspace_id || x.workspace_id || null;
const projectId = valReq.project_id ?? x.project_id ?? null;
const conversationId = valReq.conversation_id ?? x.conversation_id ?? null;
const workflowId = valReq.workflow_id ?? x.workflow_id ?? null;
const workflowName = valReq.workflow_name ?? x.workflow_name ?? null;

const status = x._final_status || 'failed';
const data = x.ai_data || {};
const wf = x._wf || null;
const nodeCount = wf && Array.isArray(wf.nodes) ? wf.nodes.filter(n => n && typeof n === 'object').length : 0;

let connCount = 0;
if (wf && wf.connections && typeof wf.connections === 'object') {
  for (const g of Object.values(wf.connections)) {
    if (!g || typeof g !== 'object') continue;
    for (const outs of Object.values(g)) {
      if (!Array.isArray(outs)) continue;
      for (const o of outs) if (Array.isArray(o)) connCount += o.length;
    }
  }
}

const evidence = [];
const origHash = x.original_workflow_hash || valReq.original_workflow_hash || null;
const targetVer = x.target_n8n_version || valReq.target_n8n_version || null;
const blueprintRef = x.blueprint_reference || valReq.blueprint_reference || null;

if (origHash) evidence.push('original_hash=' + origHash);
if (targetVer) evidence.push('target_n8n_version=' + targetVer);
evidence.push('ai_valid=' + Boolean(x.ai_valid) + ' structural_valid=' + (x._structural_valid === true));

const limitations = [
  'Static structural checks only; import and runtime execution have not been tested.',
  'No live n8n workflow was modified by this workflow; live update handled by WF-09.',
  'Diff is authoritative; AI-reported changed_nodes NOT trusted as source of truth.',
  'user_id/workspace_id/project_id accepted from authenticated caller as-is.'
];

if (!x.ai_valid) limitations.push('AI update unavailable or invalid: ' + (x.ai_error || 'unknown'));
if (targetVer) limitations.push('Target n8n version was supplied but compatibility was NOT fully verified.');
else limitations.push('target_n8n_version not provided; version compatibility not checked.');
if (x._credentials_preserved === false) limitations.push('CRITICAL: credentials may have been dropped; verify before import.');
if (x._credentials_preserved === null) limitations.push('Credential preservation check was inconclusive.');
limitations.push(...(data.limitations || []));

const providerUsed = x.ai_valid ? (x.ai_provider || 'groq') : 'none';
const modelUsed = providerUsed === 'gemini' ? 'gemini-2.0-flash' : (providerUsed === 'groq' ? 'openai/gpt-oss-120b' : 'none');

const verificationSummary = {
  status: 'not_verified',
  evidence,
  compatibility_status: x._compatibility_status || 'not_checked',
  provider: providerUsed,
  model: modelUsed,
  credentials_preserved: x._credentials_preserved ?? null
};

const recommendedFixes = (x._all_issues || []).map((iss, i) => ({
  finding_id: 'V' + String(i + 1).padStart(3, '0'),
  fix: 'Address: ' + iss.message
}));

const result = {
  audit_id: 'UPD-' + reqId,
  audit_status: status,
  updated_workflow_json: wf,
  change_summary: data.change_summary ? String(data.change_summary).slice(0, 4000) : null,
  changed_nodes: data.changed_nodes || [],
  diff: x._diff || null,
  validation_result: {
    status: status === 'success' ? 'valid' : (x.ai_valid ? 'invalid' : 'not_produced'),
    checks_run: [
      'outer JSON parse',
      'workflow.name string',
      'nodes array',
      'connections object',
      'per-node fields',
      'duplicate ids/names',
      'connection references',
      'no inline credentials',
      'no active:true',
      'no hardcoded secret patterns',
      'credentials preservation',
      'diff computation'
    ],
    issues: x._all_issues || [],
    issues_total: (x._all_issues || []).length,
    essentials_notes: x._essentials_notes || []
  },
  assumptions: data.assumptions || [],
  unresolved_issues: data.unresolved_issues || [],
  limitations,
  recommended_fixes: recommendedFixes,
  rollback_reference: x.rollback_reference || null,
  verification_summary: verificationSummary,
  target_n8n_version: targetVer,
  blueprint_reference: blueprintRef,
  node_count: nodeCount,
  connection_count: connCount
};

const httpStatus = status === 'failed' ? 500 : 200;
const errors = [];
if (!x.ai_valid && x.ai_error) errors.push({ category: x.ai_error_category || 'MODEL_ERROR', message: 'AI update unavailable: ' + x.ai_error });
if (x.ai_valid && !x._structural_valid) errors.push({ category: 'VALIDATION_FAILED', message: 'Updated workflow failed structural checks', details: (x._all_issues || []).slice(0, 10).map(i => i.message) });
if (x._credentials_preserved === false) errors.push({ category: 'VALIDATION_FAILED', message: 'Credentials dropped during update; manual review required' });

const warnings = status === 'partial' ? [{ message: 'Update incomplete or validation issues present' }] : [];

return [{
  json: {
    request_id: reqId,
    task_id: null,
    status: status === 'success' ? 'completed' : (status === 'partial' ? 'partial' : 'failed'),
    _http_status: httpStatus,
    result,
    errors,
    warnings,
    verification: verificationSummary,
    _persist: {
      project_id: projectId,
      user_id: userId,
      claimed_user_id: userId,
      workspace_id: workspaceId,
      conversation_id: conversationId,
      workflow_id: workflowId,
      workflow_name: workflowName,
      node_count: nodeCount
    }
  }
}];

let src = null;
try {
  const a = $('Build Result').first()?.json;
  if (a && a.result) src = a;
} catch (e) {}
if (!src) {
  try {
    const b = $('Format Request Error').first()?.json;
    if (b && b.result) src = b;
  } catch (e) {}
}
const fallbackReqId = $('Validate Request').first()?.json?.request_id || 'fallback-id';
if (!src) {
  src = {
    request_id: fallbackReqId,
    status: 'failed',
    result: { audit_id: 'UPD-' + fallbackReqId, audit_status: 'failed' },
    verification: { status: 'not_verified', evidence: [] },
    errors: [],
    task_id: null,
    warnings: [],
    _persist: {}
  };
}
if (!src.request_id) src.request_id = fallbackReqId;

const row = $input.first()?.json ?? {};
const id = row.id ?? row.audit_id ?? src.result?.audit_id ?? null;
const idOk = typeof id === 'string' ? id.trim().length > 0 : (typeof id === 'number' && isFinite(id));
const checks = [];
if (!idOk) checks.push('no valid record id');
if (row.project_id !== undefined && row.project_id !== null && src._persist && src._persist.project_id && row.project_id !== src._persist.project_id) checks.push('project_id mismatch');
if (row.request_id !== undefined && row.request_id !== null && src.request_id && row.request_id !== src.request_id) checks.push('request_id mismatch');

const ok = idOk && checks.length === 0;
const verification = { ...(src.verification || {}), persisted: ok, persist_record_id: idOk ? id : null, persist_checks: checks };
const result = { ...(src.result || {}), verification_summary: verification };

return [{
  json: {
    ...src,
    request_id: src.request_id || fallbackReqId,
    status: ok ? src.status : 'partial',
    result,
    verification,
    errors: ok ? (src.errors || []) : [...(src.errors || []), { category: 'INTERNAL_ERROR', message: 'Persistence unconfirmed: ' + checks.join('; ') }]
  }
}];
